import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import test from 'node:test';
import { DocumentParser } from '/home/liuxuedeng/Django-Agent/packages/core/src/documents/parser.ts';

const repo='/home/liuxuedeng/Django-Agent';
const fixture=join(repo,'workers/document/tests/fixtures');
const parser=new DocumentParser({pythonExecutable:'/tmp/marlin-parser-isolation-20261010/bin/python',workerPath:join(repo,'workers/document/worker.py')});
async function parse(path, root) {
  const data=await readFile(path), artifact=await mkdtemp(join(root,'artifacts-'));
  return parser.parse({input:{path,name:path.split('/').at(-1),sha256:createHash('sha256').update(data).digest('hex'),size_bytes:data.length},artifact_dir:artifact});
}
async function temporary(work) {
  const root=await mkdtemp(join(tmpdir(),'marlin-image-bridge-'));
  try { await work(root); } finally { await rm(root,{recursive:true,force:true}); }
}
test('real bridge rejects a corrupt standalone PNG with the existing private parse_failed error',async()=>temporary(async root=>{
  await assert.rejects(parse(join(fixture,'bad.png'),root),{code:'parse_failed',retryable:false,message:'The document could not be parsed'});
}));
test('real bridge rejects malformed standalone SVG',async()=>temporary(async root=>{
  const path=join(root,'malformed.svg'); await writeFile(path,'<svg xmlns="http://www.w3.org/2000/svg"><unclosed');
  await assert.rejects(parse(path,root),{code:'parse_failed',retryable:false});
}));
test('real bridge still accepts empty TXT, image-only PNG and scanned PDF, and small-image warnings',async()=>temporary(async root=>{
  for (const name of ['empty.txt','image.png','scanned.pdf','small.png']) {
    const result=await parse(join(fixture,name),root);
    assert.equal(result.document.canonical_text,'');
    if(name==='image.png'||name==='scanned.pdf') assert.ok(result.blocks.some(block=>block.kind==='image'));
    if(name==='small.png') assert.equal(result.warnings[0].code,'invalid_or_small_image');
  }
}));
test('real bridge preserves usable Markdown text and corrupt embedded-image warnings',async()=>temporary(async root=>{
  const source='Before\n\n![broken](data:image/png;base64,bm90IGFuIGltYWdl)\n\nAfter';
  const path=join(root,'embedded.md'); await writeFile(path,source);
  const result=await parse(path,root);
  assert.equal(result.document.canonical_text,source);
  assert.equal(result.warnings[0].code,'image_fetch_failed');
  assert.ok(result.blocks.every(block=>block.kind==='text'));
}));
